def calculate(operation: str, a: float, b: float) -> float:
    if operation == 'add':
        return a + b
    elif operation == 'subtract':
        return a - b
    elif operation == 'multiply':
        return a * b
    elif operation == 'divide':
        if b == 0:
            raise ValueError('0으로 나눌 수 없습니다')
        return a / b
    else:
        raise ValueError(f'지원하지 않는 연산: {operation}')

def execute_tool(tool_name: str, tool_input: dict, tools_map: dict) -> str:
    if tool_name not in tools_map:
        return f'알 수 없는 도구: {tool_name}'
    try:
        result = tools_map[tool_name](**tool_input)
        return str(result)
    except Exception as e:
        return f'도구 실행 오류: {e}'

def build_tool_result_message(tool_use_block, result: str) -> dict:
    return {
        'role': 'user',
        'content': [{
            'type': 'tool_result',
            'tool_use_id': tool_use_block.id,
            'content': result
        }]
    }

def run_agent_safe(client, messages, tools, tools_map, max_iterations=10):
    for _ in range(max_iterations):
        response = client.messages.create(
            model='claude-3-5-haiku-20241022',
            max_tokens=1024,
            tools=tools,
            messages=messages
        )
        if response.stop_reason == 'tool_use':
            messages.append({'role': 'assistant', 'content': response.content})
            for block in response.content:
                if block.type == 'tool_use':
                    result = execute_tool(block.name, block.input, tools_map)
                    messages.append(build_tool_result_message(block, result))
        else:
            for block in response.content:
                if hasattr(block, 'text'):
                    return block.text
    return '최대 반복 횟수 초과'

