def calculate(operation: str, a: float, b: float) -> float:
    if operation == 'add':
        return a + b
    elif operation == 'subtract':
        return a - b
    elif operation == 'multiply':
        return a * b
    elif operation == 'divide':
        if b == 0:
            raise ValueError('0으로 나눌 수 없습니다')
        return a / b
    else:
        raise ValueError(f'지원하지 않는 연산: {operation}')

TOOLS_MAP = {'search_web': search_web, 'calculate': calculate}

def run_agent(client, user_message: str) -> str:
    messages = [{'role': 'user', 'content': user_message}]
    for _ in range(10):
        response = client.messages.create(
            model='claude-3-5-haiku-20241022',
            max_tokens=1024,
            tools=TOOLS,
            messages=messages
        )
        if response.stop_reason == 'tool_use':
            messages.append({'role': 'assistant', 'content': response.content})
            for block in response.content:
                if block.type == 'tool_use':
                    try:
                        result = TOOLS_MAP[block.name](**block.input)
                    except Exception as e:
                        result = f'오류: {e}'
                    messages.append({'role': 'user', 'content': [{'type': 'tool_result', 'tool_use_id': block.id, 'content': str(result)}]})
        else:
            for block in response.content:
                if hasattr(block, 'text'):
                    return block.text
    return '최대 반복 횟수 초과'

def run_agent_full(client, messages, tools, tools_map):
    for _ in range(15):
        response = client.messages.create(
            model='claude-3-5-haiku-20241022',
            max_tokens=2048,
            tools=tools,
            messages=messages
        )
        if response.stop_reason in ('end_turn', 'max_tokens'):
            for block in response.content:
                if hasattr(block, 'text'):
                    return block.text
            return ''
        elif response.stop_reason == 'tool_use':
            messages.append({'role': 'assistant', 'content': response.content})
            for block in response.content:
                if block.type == 'tool_use':
