async def fetch_url(session, url: str) -> dict:
    try:
        async with session.get(url) as response:
            if response.status == 200:
                return await response.json()
            else:
                return {'error': True, 'status': response.status, 'url': url}
    except aiohttp.ClientError as e:
        return {'error': True, 'message': str(e), 'url': url}

async def fetch_with_retry(session, url: str, max_retries: int = 3) -> dict:
    for attempt in range(max_retries):
        try:
            async with session.get(url) as response:
                if response.status == 200:
                    return await response.json()
        except aiohttp.ClientError:
            pass
        await asyncio.sleep(2 ** attempt)
    raise RuntimeError(f'요청 실패: {url}')

async def fetch_all_limited(urls: list, max_concurrent: int = 5, timeout_sec: float = 10.0) -> list:
    semaphore = asyncio.Semaphore(max_concurrent)
    timeout = aiohttp.ClientTimeout(total=timeout_sec)

    async def fetch_one(session, url):
        async with semaphore:
            try:
                async with session.get(url) as response:
                    if response.status == 200:
                        return await response.json()
                    return None
            except Exception:
                return None

    async with aiohttp.ClientSession(timeout=timeout) as session:
        tasks = [fetch_one(session, url) for url in urls]
        return await asyncio.gather(*tasks)

async def batch_claude_requests(client, prompts: list, system: str = '') -> list:
    async def call_claude(prompt):
        kwargs = {
            'model': 'claude-3-5-haiku-20241022',
            'max_tokens': 1024,
            'messages': [{'role': 'user', 'content': prompt}]
        }
        if system:
            kwargs['system'] = system
        response = await client.messages.create(**kwargs)
        return response.content[0].text

    tasks = [call_claude(p) for p in prompts]
    return await asyncio.gather(*tasks)

ENDPOINTS = {
    'weather': 'https://api.example.com/weather',
    'news': 'https://api.example.com/news',
    'stock': 'https://api.example.com/stock'
}

async def aggregate_data() -> dict:
    semaphore = asyncio.Semaphore(3)
    timeout = aiohttp.ClientTimeout(total=5.0)

    async def fetch_source(session, name, url):
        async with semaphore:
            try:
                async with session.get(url) as resp:
                    if resp.status == 200:
                        return name, await resp.json()
                    return name, None
            except Exception:
                return name, None

    async with aiohttp.ClientSession(timeout=timeout) as session:
        tasks = [fetch_source(session, name, url) for name, url in ENDPOINTS.items()]
        results = await asyncio.gather(*tasks)
        return dict(results)

async def stream_results(urls: list):
    async with aiohttp.ClientSession() as session:
        async def fetch_one(url):
            async with session.get(url) as resp:
                return url, await resp.json()

        tasks = {asyncio.ensure_future(fetch_one(url)): url for url in urls}

        for future in asyncio.as_completed(tasks.keys()):
            try:
                url, data = await future
                yield {'url': url, 'data': data}
            except Exception as e:
                yield {'url': '알 수 없음', 'error': str(e)}

