from fastapi import FastAPI, Depends, HTTPException
from fastapi.security import HTTPBearer, HTTPAuthorizationCredentials
from pydantic import BaseModel
from jose import jwt, JWTError
import anthropic

app = FastAPI()
client = anthropic.AsyncAnthropic()
SECRET_KEY = 'aimon-secret'
FAKE_USERS = {'admin': 'password123'}
security = HTTPBearer()

class LoginRequest(BaseModel):
    username: str
    password: str

class ChatRequest(BaseModel):
    message: str

def get_current_user(credentials: HTTPAuthorizationCredentials = Depends(security)) -> str:
    try:
        payload = jwt.decode(credentials.credentials, SECRET_KEY, algorithms=['HS256'])
        user_id = payload.get('sub')
        if not user_id:
            raise HTTPException(status_code=401, detail='인증 실패')
        return user_id
    except JWTError:
        raise HTTPException(status_code=401, detail='인증 실패')

@app.post('/auth/login')
def login(req: LoginRequest):
    if FAKE_USERS.get(req.username) != req.password:
        raise HTTPException(status_code=401, detail='잘못된 자격증명')
    token = jwt.encode({'sub': req.username}, SECRET_KEY, algorithm='HS256')
    return {'access_token': token, 'token_type': 'bearer'}

@app.post('/chat')
async def chat(req: ChatRequest, user_id: str = Depends(get_current_user)):
    response = await client.messages.create(
        model='claude-3-5-haiku-20241022',
        max_tokens=1024,
        messages=[{'role': 'user', 'content': req.message}]
    )
    return {'user': user_id, 'reply': response.content[0].text}

from langchain_community.vectorstores import FAISS
from langchain.retrievers import EnsembleRetriever

def build_ensemble_retriever(docs_list: list, embeddings, weights=None):
    retrievers = []
    for docs in docs_list:
        vectorstore = FAISS.from_documents(docs, embeddings)
        retriever = vectorstore.as_retriever(search_kwargs={'k': 3})
        retrievers.append(retriever)

    if weights is None:
        n = len(retrievers)
        weights = [1.0 / n] * n

    return EnsembleRetriever(retrievers=retrievers, weights=weights)
